[{"order":1,"type":"heading","text":"Built-in User Model, Authentication Backends, and Sessions in Django"},{"order":2,"type":"paragraph","text":"Django provides a robust, out-of-the-box authentication and authorization system. This tutorial explores the core components of this system: the built-in User model, custom authentication backends, and session management."},{"order":3,"type":"subheading","text":"1. The Built-in User Model"},{"order":4,"type":"paragraph","text":"Django's default User model includes essential fields such as username, password, email, first_name, last_name, is_staff, is_active, and is_superuser. You can interact with this model directly for user creation and authentication."},{"order":5,"type":"code","text":"from django.contrib.auth.models import User

# Creating a new user
user = User.objects.create_user('johndoe', 'john@example.com', 'securepassword123')
user.first_name = 'John'
user.save()"},{"order":6,"type":"subheading","text":"2. Authentication Backends"},{"order":7,"type":"paragraph","text":"Authentication backends are classes that verify a set of credentials. By default, Django uses ModelBackend, which checks the username and password against the database. You can create custom backends to allow login via email or third-party services."},{"order":8,"type":"code","text":"from django.contrib.auth.backends import ModelBackend
from django.contrib.auth.models import User

class EmailAuthBackend(ModelBackend):
    def authenticate(self, request, username=None, password=None, **kwargs):
        email = kwargs.get('email', username)
        try:
            user = User.objects.get(email=email)
            if user.check_password(password):
                return user
        except User.DoesNotExist:
            return None
        return None"},{"order":9,"type":"paragraph","text":"To activate your custom backend, configure the AUTHENTICATION_BACKENDS setting in your settings.py file."},{"order":10,"type":"code","text":"AUTHENTICATION_BACKENDS = [
    'myapp.backends.EmailAuthBackend',
    'django.contrib.auth.backends.ModelBackend',
]"},{"order":11,"type":"subheading","text":"3. Managing Sessions"},{"order":12,"type":"paragraph","text":"Django handles state across requests using sessions. When a user successfully logs in via the authenticate() and login() functions, the user's ID is stored in the session."},{"order":13,"type":"code","text":"from django.contrib.auth import authenticate, login, logout
from django.shortcuts import render, redirect

def login_view(request):
    if request.method == 'POST':
        username = request.POST['username']
        password = request.POST['password']
        user = authenticate(request, username=username, password=password)
        if user is not None:
            login(request, user)
            return redirect('dashboard')
    return render(request, 'login.html')

def logout_view(request):
    logout(request)
    return redirect('login')"},{"order":14,"type":"bullet_point","text":"Sessions store data on the server side while sending a cookie containing the session ID to the client browser."},{"order":15,"type":"bullet_point","text":"You can configure session storage engines in settings.py, such as database-backed sessions (default), cached sessions, or cookie-based sessions."}]
